import MenuJson from "./menus.json";
import { useI18n } from 'vue-i18n';

export default {
  name: "Navbar",
  data() {
    return {
      menu: MenuJson,
      isLanguage: Boolean,
    };
  },
  created() {},
  // mounted() {
  //   localStorage.setItem("isLanguage", true)
  //   if(localStorage.getItem("isLanguage")) {
  //     this.isLanguage = localStorage.getItem("isLanguage")
  //   }
  //   console.log(this.isLanguage)
  // },
  updated() {
    this.changeLanguage();
  },
  methods: {
    changeLanguage(){
      const { locale } = useI18n();

      if(localStorage.getItem("isLanguage")){
        localStorage.setItem("isLanguage", this.isLanguage)
      }else {
        localStorage.setItem("isLanguage", this.isLanguage)
      }
      if (localStorage.getItem("isLanguage")) {
        locale.value = 'en';
      } else {
        locale.value = 'kh';
      }
    }
  },
};
